function isNoindex(pathname) {
  if (pathname.startsWith("/commercial/")) return true;
  const m = pathname.match(/^\/guides\/([^/]+?)(?:\.html)?\/?$/);
  return !!(m && NOINDEX_GUIDES.has(m[1]));
}

export default async (request, context) => {
  const response = await context.next();
  const type = response.headers.get("content-type") || "";
  if (!type.includes("text/html")) return response;
  if (!isNoindex(new URL(request.url).pathname)) return response;
  const headers = new Headers(response.headers);
  headers.set("X-Robots-Tag", "noindex, follow");
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
};

export const config = {
  path: "/*",
  excludedPath: ["/.netlify/*", "/*.js", "/*.css", "/*.xml", "/*.json", "/*.txt", "/*.jpg", "/*.jpeg", "/*.png", "/*.webp", "/*.svg", "/*.ico"],
};
